{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Saved-object type against operation. Writes come first and reads after; cell volume is colour on a log scale, teal (fewest) through blue and purple to pink (most), so a single delete stays visible beside thousands of reads in either theme; the legend labels the fewest and the most events drawn and each decade between that sits at least a sixth of the gradient (and 2.5x) from both, so no two labels touch. An operation outside the suite's verbs keeps Kibana's own words (remove refs: saved_object_remove_references, a tag unlinked from objects), or reads \"no action\" where Kibana recorded none (a Fleet policy deploy), and sits between the changes and the reads. Past 13 object types the rest fold into one \"N more types\" row so every row stays readable at any volume; types with a write rank first, so a rare change is not the one folded.",
  "title": {
    "text": {
      "expr": "length(data('rows')) ? '' : 'No activity for this selection in this time range'"
    },
    "fontSize": {
      "expr": "length(data('rows')) ? 0 : 12"
    },
    "offset": {
      "expr": "length(data('rows')) ? 0 : 4"
    }
  },
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "config": {
    "axis": {
      "labelFontSize": 11,
      "titleFontSize": 11
    },
    "view": {
      "stroke": null
    },
    "title": {
      "fontSize": 12,
      "fontWeight": 500,
      "anchor": "start"
    },
    "legend": {
      "labelFontSize": 11,
      "titleFontSize": 11
    },
    "scale": {
      "rectBandPaddingInner": 0.08
    }
  },
  "data": {
    "name": "rows",
    "url": {
      "%type%": "esql",
      "query": "SET unmapped_fields=\"nullify\"; FROM logs-elastic_cloud.serverless_audit.otel-* | WHERE @timestamp <= ?_tend AND @timestamp > ?_tstart | WHERE service.name == \"serverless-kibana\" | GROK body.text \"\"\"\\[(?:id|workflowId)=%{DATA:g_id}(?:,|\\])\"\"\" | EVAL obj_id = COALESCE(kibana.saved_object.id, g_id) | WHERE obj_id IS NOT NULL | STATS n = COUNT(*) BY event.action, kibana.saved_object.type, obj_id | EVAL verb = CASE(event.action LIKE \"*_execution_cancel\", \"cancel\", event.action LIKE \"*_run_soon\", \"run\", event.action LIKE \"*_run\", \"run\", event.action LIKE \"*_test\", \"test\", event.action LIKE \"*_enable\", \"enable\", event.action LIKE \"*_disable\", \"disable\", event.action LIKE \"ml_put_*\", \"create\", event.action LIKE \"ml_open_*\", \"open\", event.action LIKE \"ml_start_*\", \"start\", event.action LIKE \"*point_in_time\", \"pit\", event.action LIKE \"*_create*\", \"create\", event.action LIKE \"*_update*\", \"update\", event.action LIKE \"*_delete\", \"delete\", event.action LIKE \"*_find\", \"find\", event.action LIKE \"*_get\", \"get\", event.action LIKE \"*_resolve\", \"resolve\", \"other\") | EVAL verb = CASE(verb == \"other\", COALESCE(event.action, \"no action\"), verb) | EVAL obj_type = CASE(kibana.saved_object.type IS NOT NULL, kibana.saved_object.type, event.action LIKE \"ml_*ad_job\", \"ml-job\", event.action LIKE \"ml_*ad_datafeed\", \"ml-datafeed\", event.action LIKE \"workflow_execution_*\", \"workflow-execution\", event.action LIKE \"workflow_*\", \"workflow\", event.action LIKE \"agent_builder_agent_*\", \"agent-builder-agent\", event.action LIKE \"agent_builder_tool_*\", \"agent-builder-tool\", event.action LIKE \"product_documentation_*\", \"product-documentation\", event.action == \"secret_create\", \"secret\", event.action IS NULL, \"unclassified\", REPLACE(event.action, \"_(create|update|delete|enable|disable|run|run_soon|test|cancel)$\", \"\")) | STATS events = SUM(n), objects = COUNT_DISTINCT(obj_id) BY so_type = obj_type, verb",
      "%timefield%": "@timestamp",
      "%context%": true
    }
  },
  "transform": [
    {
      "calculate": "replace(replace(replace(datum.verb, regexp('^saved_object_'), ''), regexp('_references$'), '_refs'), regexp('_', 'g'), ' ')",
      "as": "verb"
    },
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "events",
          "as": "type_events"
        }
      ],
      "groupby": [
        "so_type"
      ]
    },
    {
      "calculate": "indexof(['get','find','resolve','pit','other'], datum.verb) < 0 ? datum.events : 0",
      "as": "write_events"
    },
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "write_events",
          "as": "type_writes"
        }
      ],
      "groupby": [
        "so_type"
      ]
    },
    {
      "calculate": "(datum.type_writes > 0 ? 1e12 : 0) + datum.type_events",
      "as": "priority"
    },
    {
      "window": [
        {
          "op": "dense_rank",
          "as": "type_rank"
        }
      ],
      "sort": [
        {
          "field": "priority",
          "order": "descending"
        },
        {
          "field": "so_type",
          "order": "ascending"
        }
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "max",
          "field": "type_rank",
          "as": "type_count"
        }
      ]
    },
    {
      "calculate": "datum.type_rank <= 13 || datum.type_count <= 14",
      "as": "kept"
    },
    {
      "calculate": "datum.kept ? datum.so_type : (datum.type_count - 13) + ' more types'",
      "as": "row"
    },
    {
      "calculate": "datum.kept ? datum.type_events : -1",
      "as": "row_order"
    },
    {
      "aggregate": [
        {
          "op": "sum",
          "field": "events",
          "as": "events"
        },
        {
          "op": "sum",
          "field": "objects",
          "as": "objects"
        },
        {
          "op": "distinct",
          "field": "so_type",
          "as": "types"
        },
        {
          "op": "max",
          "field": "row_order",
          "as": "row_order"
        }
      ],
      "groupby": [
        "row",
        "verb"
      ]
    },
    {
      "calculate": "indexof(['create','update','delete','enable','disable','run','test','cancel','open','start'], datum.verb) >= 0 ? indexof(['create','update','delete','enable','disable','run','test','cancel','open','start'], datum.verb) : indexof(['get','find','resolve','pit','other'], datum.verb) >= 0 ? 100 + indexof(['get','find','resolve','pit','other'], datum.verb) : 50",
      "as": "col_order"
    }
  ],
  "encoding": {
    "y": {
      "field": "row",
      "type": "nominal",
      "sort": {
        "op": "max",
        "field": "row_order",
        "order": "descending"
      },
      "axis": {
        "title": "Object type",
        "labelLimit": 200,
        "titleOpacity": {
          "expr": "length(data('rows')) ? 1 : 0"
        },
        "domainOpacity": {
          "expr": "length(data('rows')) ? 1 : 0"
        }
      }
    },
    "x": {
      "field": "verb",
      "type": "nominal",
      "sort": {
        "field": "col_order",
        "op": "min",
        "order": "ascending"
      },
      "axis": {
        "title": "Operation",
        "labelAngle": {
          "expr": "bandwidth('x') < 44 ? -40 : 0"
        },
        "orient": "top",
        "titleOpacity": {
          "expr": "length(data('rows')) ? 1 : 0"
        },
        "domainOpacity": {
          "expr": "length(data('rows')) ? 1 : 0"
        },
        "labelExpr": "bandwidth('x') < 44 ? datum.label : length(split(datum.label, ' ')) > 1 ? split(datum.label, ' ') : ['', datum.label]",
        "labelLineHeight": 12,
        "labelBaseline": {
          "expr": "bandwidth('x') < 44 ? 'middle' : 'alphabetic'"
        },
        "titlePadding": 6,
        "labelPadding": {
          "expr": "bandwidth('x') < 44 ? 4 : 16"
        },
        "labelAlign": {
          "expr": "bandwidth('x') < 44 ? 'left' : 'center'"
        }
      }
    },
    "tooltip": [
      {
        "field": "row",
        "title": "Object type"
      },
      {
        "field": "verb",
        "title": "Operation"
      },
      {
        "field": "events",
        "title": "Events",
        "format": ","
      },
      {
        "field": "objects",
        "title": "Distinct objects",
        "format": ","
      },
      {
        "field": "types",
        "title": "Object types in this row"
      }
    ]
  },
  "layer": [
    {
      "mark": {
        "type": "rect",
        "cornerRadius": 2
      },
      "encoding": {
        "color": {
          "field": "events",
          "type": "quantitative",
          "scale": {
            "type": "log",
            "range": [
              "#54B399",
              "#6092C0",
              "#9170B8",
              "#D36086"
            ],
            "interpolate": "hcl"
          },
          "legend": {
            "title": "Events",
            "orient": "right",
            "direction": "vertical",
            "gradientLength": 140,
            "gradientThickness": 10,
            "values": {
              "expr": "!(length(data('rows'))) ? [] : domain('color')[1] > domain('color')[0] ? ((floor(log(domain('color')[1] / max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 + 1e-9) - ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 1) <= 0 ? [domain('color')[0], domain('color')[1]] : (floor(log(domain('color')[1] / max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 + 1e-9) - ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 1) == 1 ? [domain('color')[0], pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 0), domain('color')[1]] : (floor(log(domain('color')[1] / max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 + 1e-9) - ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 1) == 2 ? [domain('color')[0], pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 0), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 1), domain('color')[1]] : (floor(log(domain('color')[1] / max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 + 1e-9) - ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 1) == 3 ? [domain('color')[0], pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 0), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 1), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 2), domain('color')[1]] : (floor(log(domain('color')[1] / max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 + 1e-9) - ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 1) == 4 ? [domain('color')[0], pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 0), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 1), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 2), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 3), domain('color')[1]] : (floor(log(domain('color')[1] / max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 + 1e-9) - ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 1) == 5 ? [domain('color')[0], pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 0), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 1), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 2), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 3), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 4), domain('color')[1]] : (floor(log(domain('color')[1] / max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 + 1e-9) - ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 1) == 6 ? [domain('color')[0], pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 0), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 1), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 2), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 3), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 4), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 5), domain('color')[1]] : (floor(log(domain('color')[1] / max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 + 1e-9) - ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 1) == 7 ? [domain('color')[0], pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 0), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 1), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 2), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 3), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 4), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 5), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 6), domain('color')[1]] : (floor(log(domain('color')[1] / max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 + 1e-9) - ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 1) == 8 ? [domain('color')[0], pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 0), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 1), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 2), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 3), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 4), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 5), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 6), pow(10, ceil(log(domain('color')[0] * max(2.5, pow(domain('color')[1] / domain('color')[0], 0.17))) / LN10 - 1e-9) + 7), domain('color')[1]] : [domain('color')[0], domain('color')[1]]) : [domain('color')[0]]"
            },
            "labelExpr": "format(datum.value, '.2~s')",
            "titleOpacity": {
              "expr": "length(data('rows')) ? 1 : 0"
            },
            "labelOpacity": {
              "expr": "length(data('rows')) ? 1 : 0"
            },
            "gradientOpacity": {
              "expr": "length(data('rows')) ? 1 : 0"
            }
          }
        }
      }
    }
  ]
}
